 2| stack<string> _88MPH(unordered_map<string, list<edge>> mapOfChargingStations, unordered_map<string, double> chargingStation, string startingLocation, double initialBattery){
 3|     // Initialize an empty stack to store the path
 4|     stack<string> stationPath;
 5|     // Declare a string variable to store the name of the current station
 6|     string stationName = "";
 7| 
 8|     // Initialize variables to store battery charge and other parameters
 9|     double currentBattery = initialBattery;
10|     double decreaseBattery = 0.0;
11|     double currentDistance = 0.0;
12|     double charge = chargingStation[startingLocation];
13| 
14|     // If the initial battery is zero or negative, return an empty path
15|     if(currentBattery <= 0.0)
16|         return {};
17| 
18|     // Charge the battery based on the charging station's power
19|     currentBattery = currentBattery + charge;
20| 
21|     // If the battery charge exceeds 75.5, return an empty path
22|     if(currentBattery > 75.5)
23|         return {};
24|     
25|     // If the battery charge is between 62.5 and 75.5 (inclusive), push the starting location onto the path and return
26|     if(currentBattery >= 62.5 && currentBattery <= 75.5){
27|         stationPath.push(startingLocation);
28|         return stationPath;
29|     }
30| 
31|     // Iterate over neighbors of the starting location in the map of charging stations
32|     for(auto& neighbor : mapOfChargingStations[startingLocation]){
33|         // Extract neighbor's station name and distance
34|         stationName = neighbor.station;
35|         currentDistance = neighbor.distance;
36|         // Calculate battery decrease based on distance traveled
37|         if (currentDistance > (numeric_limits<double>::max() / 0.346)) {
38|             return {};
39|         }
40|         decreaseBattery = currentDistance * 0.346;
41|         // Recursively call _88MPH function with updated parameters
42|         stationPath = _88MPH(mapOfChargingStations, chargingStation, stationName, currentBattery-decreaseBattery);
43|          
44|         // If a non-empty path is found, push the starting location onto the path and break the loop
45|         if(!stationPath.empty()){
46|             stationPath.push(startingLocation);
47|             break;
48|         }
49|     }
50| 
51|     // Return the resulting station path
52|     return stationPath;
53| }

